from pages import L,IG,FB,ADS,META,EU,STEPS
CORE=[IG[1],IG[0],IG[2],FB[0],FB[1],FB[2],FB[3],ADS[2]]
FAM=[('en','https://unbanz.com/meta-appeal-links-and-forms-directory/'),('fr','https://unbanz.com/fr/liens-officiels-appel-meta-instagram-facebook/'),('nl','https://unbanz.com/nl/officiele-bezwaarlinks-meta-instagram-facebook/'),('x-default','https://unbanz.com/meta-appeal-links-and-forms-directory/')]
def country(slug,cn,adj,extra,reports,pre_extra,faq_extra,rel_extra,hl):
    return dict(slug=slug,title=f'Meta Appeal Links for the {cn} (2026): Instagram, Facebook, Ads' if cn in('USA','UK') else f'Meta Appeal Links for {cn} (2026): Instagram, Facebook, Ads',crumb=f'Meta appeal links: {cn}',listname='',
     hreflang=[('en-'+hl,f'https://unbanz.com/{slug}/')],
     desc=f'Official Instagram, Facebook and Meta ad account appeal links for people in the {cn}, plus the {adj} places to report hacking or fraud. What each one is for. Checked November 2026.'.replace('the Canada','Canada'),
     h1=f'Meta appeal links for {"the " if cn in ("USA","UK") else ""}{cn}.',lede=f'The official Instagram, Facebook and ad account routes, and the {adj} reporting bodies that matter when an account is hacked or used for fraud.',
     answer=f'<strong>The Meta appeal routes are the same in {"the " if cn in ("USA","UK") else ""}{cn} as everywhere else:</strong> appeal a disabled or suspended Instagram or Facebook account from the notice you see when you log in, use instagram.com/hacked or facebook.com/hacked for takeovers, and request ad account reviews in Business Support Home. Meta has no general support phone number. {extra} Meta makes the final decision.',
     cards=[('Same routes','In-app notice, hacked pages, Business Support Home.'),(f'{adj.capitalize()} reporting','For hacking and money lost.'),('No phone line','Meta has no general support number.')],
     pre='<h2 id="which-link">Which link do you need?</h2><ul><li>Disabled or suspended notice: appeal from that screen. See '+L('guides/facebook-account-disabled-appeal','Facebook appeal')+' or '+L('guides/instagram-account-suspended-appeal','Instagram appeal')+'.</li><li>Hacked: the hacked links below, then the reporting bodies if money or identity is involved.</li><li>Ad account restricted: '+L('meta-ad-account-appeal-links-directory','ad account links')+'.</li></ul>'+pre_extra,
     sections=[('meta-links','Official Meta links',CORE),('report',f'Where to report in the {cn}'.replace('the Canada','Canada'),reports)],
     post=[STEPS],related=L('meta-appeal-links-and-forms-directory','Meta appeal links directory')+', '+L('how-to-contact-meta-about-a-disabled-account','how to contact Meta')+', '+rel_extra,
     faqs=[(f'Is there a Meta support number in the {cn}?'.replace('the Canada','Canada'),'No. Meta says it has no general public phone number for customer service. Numbers claiming to be Meta support are likely scams.'),('Where do I appeal a disabled Instagram or Facebook account?','From the notice you see when you log in, or from Account Status and Accounts Center.')]+faq_extra)
PAGES=[
country('meta-appeal-links-usa','USA','US','If a hacker spent money or stole your identity, you can also report to the FTC and the FBI’s IC3; those reports do not restore an account but create a record.',
 [('ReportFraud.ftc.gov','https://reportfraud.ftc.gov/','The Federal Trade Commission’s fraud reporting site. Useful when a hacked account was used to scam people or charge your card.'),('IdentityTheft.gov','https://www.identitytheft.gov/','For identity theft: a recovery plan and a report you can show your bank.'),('FBI IC3','https://www.ic3.gov/','The FBI’s Internet Crime Complaint Center, for hacking and online fraud with a loss.')],
 '<h2 id="state">State attorneys general</h2><p>Some people also contact their state attorney general’s consumer office. It does not reopen a Meta decision, but it is a formal record. See '+L('ftc-and-state-attorney-general-complaint-meta-account','FTC and state attorney general complaints')+'.</p>',
 [('Will an FTC report get my account back?','No. It records the fraud. The account itself is decided by Meta through its appeal routes.')],
 L('instagram-suspended-appeal-usa','Instagram suspended in the US')+', '+L('facebook-account-disabled-usa-what-to-do','Facebook disabled in the US')+', '+L('report-hacked-account-police-action-fraud-ic3','reporting a hacked account')+'.','US'),
country('meta-appeal-links-uk','UK','UK','If you lost money or were scammed through a hacked account, report it to Action Fraud. If you want the data Meta holds about your account, a UK GDPR subject access request is an option.',
 [('Action Fraud','https://www.actionfraud.police.uk/','The UK’s reporting centre for fraud and cyber crime in England, Wales and Northern Ireland. Scotland reports to Police Scotland on 101.'),('Information Commissioner’s Office (ICO)','https://ico.org.uk/','The UK data protection regulator. Relevant if a subject access request to Meta is not answered.')],
 '<h2 id="sar">Subject access request</h2><p>Under UK GDPR you can ask Meta for the personal data it holds about you, which can include information about your account. It is not an appeal. See '+L('uk-gdpr-subject-access-request-meta-disabled-account','UK GDPR subject access request')+'.</p>',
 [('Can I use the EU Appeals Centre from the UK?','Appeals Centre Europe is set up under the EU Digital Services Act for people in the EU. UK users use Meta’s own appeal.')],
 L('instagram-suspended-appeal-uk','Instagram suspended in the UK')+', '+L('facebook-account-disabled-uk-what-to-do','Facebook disabled in the UK')+', '+L('report-hacked-account-police-action-fraud-ic3','reporting a hacked account')+'.','GB'),
country('meta-appeal-links-canada','Canada','Canadian','If a hacked account was used to scam people or take money, report it to the Canadian Anti-Fraud Centre and your local police.',
 [('Canadian Anti-Fraud Centre','https://antifraudcentre-centreantifraude.ca/','The national centre for reporting fraud and scams, including social media account takeovers used for scams.'),('Office of the Privacy Commissioner of Canada','https://www.priv.gc.ca/','The federal privacy regulator, for questions about access to your personal information.')],
 '<h2 id="bilingual">French and English</h2><p>Meta’s help pages and appeal screens are available in French and English. Use the language you are most comfortable writing in; a clear appeal matters more than the language.</p>',
 [('Should I contact the police if my account was hacked?','If money was taken or the account was used to scam people, yes: a report creates a record. It does not restore the account.')],
 L('instagram-suspended-appeal-canada','Instagram suspended in Canada')+', '+L('facebook-account-disabled-canada-what-to-do','Facebook disabled in Canada')+', '+L('canada-australia-hacked-or-banned-account-where-to-report','where to report in Canada and Australia')+'.','CA'),
dict(slug='facebook-business-owner-profile-suspended',title='Facebook Suspended a Business Owner’s Profile: Keep the Business Running',crumb='Business owner profile suspended',listname='',
 desc='Your personal Facebook profile was suspended and it runs your business Page, shop or ads. What happens to the Page and ad account, how to appeal, and how to keep the business going meanwhile.',
 h1='Your Facebook profile is suspended and it runs the business.',lede='When the personal profile behind a Page, shop or ad account is suspended, and the business stops with it.',
 answer='<strong>Appeal the personal profile from its suspension notice first; that is what unlocks everything else.</strong> A Page or ad account is managed through people, so if you are the only admin, the business is stuck until the profile is back. If another trusted person already has full control of the Page or Business Portfolio, they can keep things running. Email verification alone does not lift a suspension. Do not open a new profile to get around it. Meta makes the final decision.',
 cards=[('Profile first','The appeal on the profile is the key.'),('Second admin','A trusted admin keeps the Page alive.'),('No workarounds','New profiles can make it worse.')],
 pre='<h2 id="what-happens">What happens to the business</h2><ul><li><strong>Page:</strong> stays visible in most situations, but nobody can post or reply if you were the only admin.</li><li><strong>Ad account:</strong> ads may stop, and the profile may be marked as unable to advertise.</li><li><strong>Shop and Marketplace:</strong> listings tied to the profile may be paused.</li><li><strong>Messages:</strong> customer messages keep arriving but go unanswered.</li></ul>'
  '<h2 id="appeal">Appealing as a business owner</h2><p>Write from the point of view of a real person who runs a real business. Give your name, the business name, what it sells and how you use Facebook for it. If something unusual happened, such as a hack, a new phone or a spike in friend requests or messages, say so. Keep it short. If the notice asks for ID or a video selfie, use your real details.</p>',
 sections=[('links','Where to go',[FB[0],FB[1],FB[2],ADS[2],ADS[1]])],
 post=['<h2 id="meanwhile">While you wait</h2><ol><li>If a colleague has full Page or Business Portfolio control, let them post a short notice and answer customers.</li><li>Tell regular customers on WhatsApp, email or your website how to reach you.</li><li>Do not create a new profile or Page to replace the old one.</li><li>Once you are back, add a second trusted admin with two-factor turned on.</li></ol>',STEPS],
 related=L('facebook-appeal-links-and-forms-directory','Facebook appeal links')+', '+L('facebook-profile-disabled-managing-business-pages','profile disabled while managing Pages')+', '+L('facebook-page-restricted-small-business-what-to-do','Page restricted for a small business')+', '+L('facebook-unban-service','Facebook unban help')+'.',
 faqs=[('Will my business Page be deleted?','Not automatically. A Page with no admin who has full control can eventually be disabled, so a second admin matters.'),('I verified my email but the account is still suspended. Why?','Email verification confirms the login. The suspension is a separate decision that only the appeal can change.'),('Can I just create a new profile to run the Page?','No. Meta may treat that as getting around the suspension.'),('Can a business account appeal for me?','No. The personal profile has to appeal for itself.')]),
dict(slug='facebook-page-recommendations-restricted',title='Facebook Page Not Eligible for Recommendations: What It Means',crumb='Page recommendations restricted',listname='',
 desc='Your Facebook Page shows “recommendations restricted” or is not eligible to be recommended. What it means, where to see it in Page status, and how to request a review.',
 h1='Your Facebook Page’s recommendations are restricted.',lede='When Page status says your Page or its content will not be recommended to people who do not follow it.',
 answer='<strong>A recommendations restriction means Facebook will not suggest your Page or some posts to people who do not already follow you.</strong> The Page is not removed and followers can still see it. You can see the reason in Page status (Professional dashboard, then Page status), and you can often request a review there or wait for the restriction to clear after the problem stops. Meta makes the final decision.',
 cards=[('Not removed','Followers still see your posts.'),('Page status','Shows the reason and any review button.'),('Fix the cause','Remove or change the flagged posts.')],
 pre='<h2 id="where">Where to check</h2><ol><li>Switch to the Page.</li><li>Open Professional dashboard, then Page status (sometimes called Account Status).</li><li>Look for Recommendations, the posts named, and Request review or Disagree with decision.</li></ol>'
  '<h2 id="why">Common reasons</h2><ul><li>Posts reused or copied from other Pages without adding anything.</li><li>Clickbait or engagement bait, such as “comment YES”.</li><li>Sensational health or financial claims.</li><li>Several Community Standards strikes in a short period.</li><li>A sudden name or topic change on an established Page.</li></ul>',
 sections=[('links','Useful official pages',[('Facebook Help Center','https://www.facebook.com/help/','Search “Page status” and “recommendations guidelines” for the current wording.'),META[2],ADS[2]])],
 post=['<h2 id="what-to-do">What to do</h2><ol><li>Read the reason and the posts it names.</li><li>Remove or edit posts that break the guidelines.</li><li>Request a review once if you think the decision is wrong.</li><li>Post original content for a while; restrictions often clear when the problem stops.</li></ol><h2 id="ads">Can I still advertise?</h2><p>A recommendations restriction is not an ad restriction, though the same posts may be rejected as ads. If ads are blocked, see '+L('facebook-page-restricted-cannot-advertise','Page restricted from advertising')+'.</p>'],
 related=L('facebook-appeal-links-and-forms-directory','Facebook appeal links')+', '+L('guides/instagram-reach-drop-recommendation-eligibility','Instagram recommendation eligibility')+', '+L('facebook-page-restricted-small-business-what-to-do','Page restricted for a small business')+'.',
 faqs=[('Is my Page shadowbanned?','“Recommendations restricted” is Facebook’s own label for limited reach to non-followers. Page status shows it.'),('Do followers still see my posts?','Yes. The restriction affects suggestions to people who do not follow you.'),('How long does it last?','Facebook does not publish a set period. Some restrictions clear once the issue stops.'),('Can I request a review?','Often yes, from Page status, if the option is shown.')]),
dict(slug='facebook-confirm-email-or-activate-account-help',title='Facebook Asks You to Confirm Your Email or Activate Your Account',crumb='Confirm email or activate account',listname='',
 desc='Facebook keeps asking you to confirm your email or “activate” your account, the code never arrives, or you cannot open the email account. What each prompt means and what to try.',
 h1='Facebook wants you to confirm your email or activate your account.',lede='When Facebook asks for a code you do not get, or you are not sure if your account is deactivated, disabled or just unconfirmed.',
 answer='<strong>First work out which of three things you are looking at.</strong> A confirmation prompt means Facebook wants proof you own the email or phone, and the code is sent there. A deactivated account is one you turned off yourself and you reactivate it by logging in. A disabled or suspended account is Meta’s decision and needs the appeal on the notice. If the code does not arrive, check spam, try the phone option, and make sure you can actually open the email account. Facebook cannot open your email for you.',
 cards=[('Confirm','A code to your email or phone.'),('Deactivated','You turned it off; log in to reactivate.'),('Disabled','Meta’s decision; appeal on the notice.')],
 pre='<h2 id="which">Which one is it?</h2><div class="table-wrap"><table><thead><tr><th>What you see</th><th>What it means</th></tr></thead><tbody><tr><td>“Enter the code we sent to your email”</td><td>Ownership check. The code goes to the email or phone on the account.</td></tr><tr><td>Your profile is gone but you can log in</td><td>Probably deactivated by you; logging in turns it back on.</td></tr><tr><td>“We suspended your account” or “Your account has been disabled”</td><td>A Meta decision. See '+L('facebook-appeal-links-and-forms-directory','Facebook appeal links')+'.</td></tr></tbody></table></div>'
  '<h2 id="no-code">If the code does not arrive</h2><ol><li>Check spam, promotions and other folders, and search for “Facebook”.</li><li>Wait a few minutes before requesting another code; repeated requests can be paused.</li><li>Choose the phone option if one is shown.</li><li>Make sure the address is spelt right on the prompt.</li><li>If you cannot log in to the email itself, recover the email account first with your email provider.</li></ol>',
 sections=[('links','Where to go',[FB[2],FB[1],FB[0],FB[3]])],
 post=['<h2 id="email-lost">If you no longer have the email or phone</h2><p>Use Find your account and follow the options shown; Facebook sometimes offers identity checks. See '+L('guides/facebook-lost-access-to-email-or-phone','lost access to email or phone')+' and '+L('facebook-lost-email-and-phone-at-the-same-time','lost email and phone at the same time')+'.</p>',STEPS],
 related=L('how-to-contact-meta-about-a-disabled-account','how to contact Meta')+', '+L('facebook-recovery-code-sent-to-wrong-email','code sent to the wrong email')+', '+L('facebook-no-password-reset-options-shown','no reset options shown')+'.',
 faqs=[('Can Facebook activate my account by email?','No. Facebook does not activate accounts by email request. Confirmation codes are sent to you, and appeals go through the notice.'),('I deactivated my account. How do I turn it back on?','Log in with your email or phone and password. That reactivates a self-deactivated account.'),('The code goes to an email I cannot open. What now?','Recover the email account with your email provider first, or use the phone option if it is offered.'),('Is Unbanz Facebook support?','No. Unbanz is an independent service and not affiliated with Meta.')]),
]
for p in PAGES:
    if p['slug'].startswith('meta-appeal-links-'): p['hreflang']=p['hreflang']
